sealed class FfiException: kotlin.Exception() {
    
    /**
     * Vault operations were attempted before [`crate::ZeroTerm::unlock`]
     * or [`crate::ZeroTerm::create`] succeeded.
     */
    class VaultLocked(
        ) : FfiException() {
        override val message
            get() = ""
    }
    
    /**
     * Master password rejected. The vault file is intact; retry with the
     * correct password.
     */
    class AuthenticationFailed(
        ) : FfiException() {
        override val message
            get() = ""
    }
    
    /**
     * `unlock` was called against a path that has no vault yet.
     */
    class NotInitialized(
        ) : FfiException() {
        override val message
            get() = ""
    }
    
    /**
     * `create` was called against a path that already has a vault.
     */
    class AlreadyExists(
        ) : FfiException() {
        override val message
            get() = ""
    }
    
    class NotFound(
        
        val `detail`: kotlin.String
        ) : FfiException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    /**
     * Catch-all for anything that doesn't fit a more specific case —
     * IO errors, malformed records, name collisions, etc. The `detail`
     * is `Display` of the underlying error.
     */
    class Other(
        
        val `detail`: kotlin.String
        ) : FfiException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<FfiException> {
        override fun lift(error_buf: RustBuffer.ByValue): FfiException = FfiConverterTypeFfiError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeFfiError : FfiConverterRustBuffer<FfiException> {
    override fun read(buf: ByteBuffer): FfiException {
        

        return when(buf.getInt()) {
            1 -> FfiException.VaultLocked()
            2 -> FfiException.AuthenticationFailed()
            3 -> FfiException.NotInitialized()
            4 -> FfiException.AlreadyExists()
            5 -> FfiException.NotFound(
                FfiConverterString.read(buf),
                )
            6 -> FfiException.Other(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: FfiException): ULong {
        return when(value) {
            is FfiException.VaultLocked -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is FfiException.AuthenticationFailed -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is FfiException.NotInitialized -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is FfiException.AlreadyExists -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is FfiException.NotFound -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
            is FfiException.Other -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
        }
    }

    override fun write(value: FfiException, buf: ByteBuffer) {
        when(value) {
            is FfiException.VaultLocked -> {
                buf.putInt(1)
                Unit
            }
            is FfiException.AuthenticationFailed -> {
                buf.putInt(2)
                Unit
            }
            is FfiException.NotInitialized -> {
                buf.putInt(3)
                Unit
            }
            is FfiException.AlreadyExists -> {
                buf.putInt(4)
                Unit
            }
            is FfiException.NotFound -> {
                buf.putInt(5)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
            is FfiException.Other -> {
                buf.putInt(6)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



sealed class HostAuthInput {
    
    data class Password(
        val `value`: kotlin.String) : HostAuthInput() {
        companion object
    }
    
    data class PrivateKey(
        val `keyPem`: kotlin.String, 
        val `passphrase`: kotlin.String?) : HostAuthInput() {
        companion object
    }
    
    object Agent : HostAuthInput()
    
    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeHostAuthInput : FfiConverterRustBuffer<HostAuthInput>{
    override fun read(buf: ByteBuffer): HostAuthInput {
        return when(buf.getInt()) {
            1 -> HostAuthInput.Password(
                FfiConverterString.read(buf),
                )
            2 -> HostAuthInput.PrivateKey(
                FfiConverterString.read(buf),
                FfiConverterOptionalString.read(buf),
                )
            3 -> HostAuthInput.Agent
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: HostAuthInput) = when(value) {
        is HostAuthInput.Password -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`value`)
            )
        }
        is HostAuthInput.PrivateKey -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`keyPem`)
                + FfiConverterOptionalString.allocationSize(value.`passphrase`)
            )
        }
        is HostAuthInput.Agent -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
    }

    override fun write(value: HostAuthInput, buf: ByteBuffer) {
        when(value) {
            is HostAuthInput.Password -> {
                buf.putInt(1)
                FfiConverterString.write(value.`value`, buf)
                Unit
            }
            is HostAuthInput.PrivateKey -> {
                buf.putInt(2)
                FfiConverterString.write(value.`keyPem`, buf)
                FfiConverterOptionalString.write(value.`passphrase`, buf)
                Unit
            }
            is HostAuthInput.Agent -> {
                buf.putInt(3)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}






